// Elix is a JavaScript project, but we define TypeScript declarations so we can
// confirm our code is type safe, and to support TypeScript users.

import ComposedFocusMixin from "elix/src/base/ComposedFocusMixin.js";
import DelegateInputLabelMixin from "elix/src/base/DelegateInputLabelMixin.js";
import FocusVisibleMixin from "elix/src/base/FocusVisibleMixin.js";
import WrappedStandardElement from "elix/src/base/WrappedStandardElement.js";

export default class Button extends ComposedFocusMixin(
  DelegateInputLabelMixin(FocusVisibleMixin(WrappedStandardElement))
) {}
